// pivots: non-alternating, strength X, EL SwingHigh/SwingLow semantics (mixed >= older / > newer)
if (active && (low[0] < chanLow || high[0] > chanHigh)) active = false;
if (!active) {
  // scan confirmed X-bar pivots newest-first inside maxLookback for the most recent pair (A, B):
  //   B = the first X-bar pivot (either type) whose bar is newer than A, and B is of the OPPOSITE type to A;
  //   A swing low:  low[a]  == lowest(low, Y)[a]   (ordering LH: chanLow = low[a],  chanHigh = high[b])
  //   A swing high: high[a] == highest(high, Y)[a] (ordering HL: chanHigh = high[a], chanLow = low[b])
  //   and lowest(low, a + 1)[0] >= chanLow && highest(high, a + 1)[0] <= chanHigh  (nothing since A took either side out)
  if (found) { active = true; latch chanLow, chanHigh, ordering, barA, barB; }
}
// barA/barB advance by one each bar while latched

if (!active) return false;
tol = touchTolAtr * atr(atrLength);
hitB = most recent j in 0..barA with low[j]  <= chanLow + tol;   // bottom hit (bars ago)
hitT = most recent j in 0..barA with high[j] >= chanHigh - tol;  // top hit
if (!(hitB < hitT)) return false;                                // bottom is the most recently hit side
h2 = the FIRST innerStrength-bar swing high whose bar is newer than hitB;
l2 = the FIRST innerStrength-bar swing low whose bar is newer than h2;
return h2 found && l2 found && barsAgo(l2) == innerStrength      // l2 confirmed on this bar
    && low[l2] > chanLow + tol;                                  // fails short of the hit side

if (!active || ordering != HL) return false;
p = the FIRST X-bar pivot (either type) whose bar is newer than barB;
if (!p found || p is not a swing low || !(low[p] > chanLow)) return false;
return low[0] < low[p]
    && lowest(low, barsAgo(p) - 1)[1] >= low[p];   // no earlier bar since the pivot broke it: first time

if (!active) return false;
p1 = FIRST X-bar pivot newer than barB; p2 = FIRST pivot of the opposite type newer than p1;  // latched
innerLow = low of the swing-low one; innerHigh = high of the swing-high one;
if (!(innerLow > chanLow && innerHigh < chanHigh)) return false;
if (innerHigh - innerLow < minBoxAtr * atr(boxAtrLength)) return false;
// most recent close below the inner low, after p2 was confirmed, within maxWaitBars
k = most recent j in 1..min(maxWaitBars, barsAgo(p2) - X) with close[j] < innerLow;
return k found
    && no j in 1..k-1 with close[j] > innerLow   // first close back above
    && close[0] > innerLow;

for (b = 1; b <= maxBarsAfterBreak; ++b) {
  // pivots as of the break bar: scan strength-S swing highs from offset b + S (inlined, not SwingHigh at an offset)
  ph1, ph2 = the two most recent confirmed swing highs as of bar b;
  if (abs(ph1 - ph2) > levelTolAtr * atr(atrLength)) continue;
  R = max(ph1, ph2);
  if (!(close[b] > R)) continue;
  if (any close[j] > R for j in b+1..barsAgo(ph1)-1) continue;   // b is the FIRST close above
  s = first j in b-1..0 (oldest first) with low[j] < R;          // setup bar
  if (!s found) continue;
  if (any j in s-1..1 with close[j] < R) continue;                // invalidated after the setup bar
  if (any j in s..1 with close[j] > open[j] && close[j] > R) continue;  // an earlier signal already fired
  if (close[0] > open[0] && close[0] > R) return true;
}
return false;

rsiVal = WFSafe_RSI(close, rsiLength);   // series variable; history read as rsiVal[j]
lo = 50 - bandHalfWidth; hi = 50 + bandHalfWidth;
for (b = 1; b <= maxWaitBars; ++b) {
  if (!(rsiVal[b] < lo)) continue;
  if (any j in b+1..b+bandBars with rsiVal[j] < lo || rsiVal[j] > hi) continue;   // band held before the break
  if (any j in 1..b-1 with rsiVal[j] >= lo) continue;                            // back in the band: invalidated
  if (any j in 1..b-1 with close[j] > open[j]) continue;                         // not the first green bar
  return close[0] > open[0];
}
return false;

p1 = SwingLow(1, low, S, L); p2 = SwingLow(2, low, S, L); p3 = SwingLow(3, low, S, L);  // -1 guarded via SwingLowBar
a = atr(atrLength);
if (abs(p1 - p2) > pairTolAtr * a) return false;
gap = min(p1, p2) - p3;
if (gap < minBelowAtr * a || gap > maxBelowAtr * a) return false;
if (lowest(low, barsAgo(p3) - 1)[1] < p3) return false;   // not yet taken out
return low[0] < p3 && close[0] > p3;

r = high[lag] - low[lag];
a = atrVal[lag];                       // ATR series variable read at the bar's own offset
return r > minRangeAtr * a && r < maxRangeAtr * a
    && open[lag] - low[lag]   <= openFraction  * r
    && high[lag] - close[lag] <= closeFraction * r;

n = (int)pauseBars;
if (!LargeShapedBarAtLag(lag = n)) return false;
R = high[n] - low[n]; H = high[n];
for (j = 0; j < n; ++j)
  if (!(high[j] - low[j] < smallFraction * R && high[j] <= H + bandFraction * R && low[j] >= H - bandFraction * R)) return false;
return true;

for (k = minHoldBars + 1; k <= maxBars; ++k) {
  if (!LargeShapedBarAtLag(lag = k, bear shape)) continue;
  R = high[k] - low[k]; mid = low[k] + 0.5 * R; ext = low[k] - extFraction * R;
  if (any j in 1..k-1 with close[j] > mid || close[j] < ext) continue;
  if (close[0] > mid) return true;
}
return false;

rsiVal = WFSafe_RSI(close, rsiLength);
lo = 50 - bandHalfWidth; hi = 50 + bandHalfWidth;
for (j = 1; j <= bandBars; ++j) if (rsiVal[j] < lo || rsiVal[j] > hi) return false;
return (rsiVal[0] < lo || rsiVal[0] > hi) && close[0] > open[0];

if (!LargeShapedBarAtLag(lag = 1, minRangeAtr = 1.5, maxRangeAtr = inf, openFraction = 1/3, closeFraction = 1/3)) return false;
R = high[1] - low[1];
if (close[1] < highest(high, extremeLookback)[1] - nearAtr * atrVal[1]) return false;   // at or near the 20-bar high
return high[0] > high[1] && close[0] >= high[1] - closeZone * R;

for (b = 2; b <= maxBars; ++b) {
  if (!LargeShapedBarAtLag(lag = b, minRangeAtr = hugeAtr, maxRangeAtr = inf, openFraction = nearFraction, closeFraction = nearFraction)) continue;
  if (!(high[b] > highest(high, breakLookback)[b + 1])) continue;   // took out the X-bar high
  if (lowest(low, b)[0] < low[b]) continue;                         // invalidated: huge bar's far extreme taken out
  i = most recent j in 1..b-1 that is inside bar j+1 (high[j] < high[j+1] && low[j] > low[j+1]),
      with close[j] < open[j], high[j] - open[j] <= nearFraction * (high[j]-low[j]), close[j] - low[j] <= nearFraction * (high[j]-low[j]);
  if (!i found) continue;
  if (any j in 1..i-1 with close[j] > open[j]) continue;              // first green after the inside bar
  return close[0] > open[0];
}
return false;

cls(j): up = high[j] > highest(high, N)[j+1]; dn = low[j] < lowest(low, N)[j+1];
        H if close[j] > highest(high, N)[j+1]; L if close[j] < lowest(low, N)[j+1]; C if (up || dn) && neither; else NONE;
if (cls(0) != H) return false;
nC = 0;
for (j = 1; j <= maxSpan; ++j) {
  c = cls(j);
  if (c == NONE) continue;          // non-breakout bars skipped (open question)
  if (c == C) { ++nC; continue; }
  return c == H && nC >= minC;     // first non-C breakout candle closes the pattern
}
return false;

k = number of consecutive red bars ending at bar 0 (close[j] < open[j], j = 0..k-1), k <= maxRunBars; if (k == 0) return false;
zU, zL = the two most recent valid I2 support zones as of bar k (zL.high < zU.low);
if (!(zU && zL)) return false;
return open[k-1] >= zU.low                     // run starts at or above the upper zone
    && close[0] < zL.low
    && (k == 1 || close[1] >= zL.low);       // first close of the run below the lower zone

// written for the SHORT, as the note states it; the long side is the mirror
if (ctx.MarketPosition() >= 0) return false;
sig = ctx.BarsSinceEntry() + 1;                      // the signal bar, one bar before the entry bar
breakoutPoint = highest(high, X)[sig + 1];           // prior X-bar high as of the signal bar
return low[0] < breakoutPoint;

for (k = 1; k <= maxWaitBars; ++k) {
  if (!(ConsolidationZone(lag = k + 1) && ConsolidationBreakoutBar at offset k)) continue;   // most recent breakout
  zh = highest(high, X)[k + 1]; zl = lowest(low, X)[k + 1];
  if (any j in 1..k-1 with low[j] <= zh) return false;   // an earlier bar already came back: not the first
  return low[0] <= zh && low[0] >= zl && close[0] > zh;
}
return false;

for (k = 1; k <= maxWaitBars; ++k) {
  if (!(ConsolidationZone(lag = k + 1) && ConsolidationBreakoutBar at offset k)) continue;   // most recent breakout
  if (any j in 1..k-1 with close[j] > high[k]) return false;
  return close[0] > high[k];
}
return false;

for (j = 0; j < (int)runBars; ++j)
  if (!(emaFast[j] < emaSlow[j] && low[j] > emaSlow[j])) return false;   // emaFast/emaSlow: XAverage series variables
return true;

for (j = 0; j < (int)runBars; ++j)
  if (!(low[j] <= min(emaFast[j], emaSlow[j]) && high[j] >= max(emaFast[j], emaSlow[j]))) return false;
return true;

n = (int)containedBars;   // bars 2..X, so X = n + 1 and bar 1 is at offset n + 1
m = n + 1; R = high[m] - low[m];
if (!(close[m] > open[m] && close[m] - open[m] > bodyFraction * R && R > minRangeAtr * atrVal[m])) return false;
for (j = 1; j <= n; ++j) if (!(high[j] <= high[m] && low[j] >= low[m])) return false;
return low[0] >= low[m] && close[0] > high[m];

// state machine; tol = tolAtr * atr, depth = maxDepthAtr * atr
if (state == 0) {
  L = SwingLow(1, low, S, pivotLookback) as of bar 1;               // level anchor (open question)
  touches = count j in 1..supportLookback with abs(low[j] - L) <= tol && close[j] >= L;
  clean = no j in 1..supportLookback with close[j] < L;
  if (touches >= minSupportTouches && clean && close[0] < L) { state = 1; level = L; since = 0; resTouches = 0; }
  return false;
}
++since;
if (low[0] < level - depth || since > maxBarsBelow) { state = 0; return false; }
if (close[0] > level) { fire = resTouches >= minResistanceTouches; state = 0; return fire; }
if (high[0] >= level - tol) ++resTouches;                            // a test from below that closed below
return false;
